      desc: "炭火焼きと逸品料理を支えるのが、充実したドリンクメニューだ。日本酒は全国各地の銘酒を取り揃えており、季節ごとに入れ替わるラインナップが楽しい。辛口から甘口まで幅広く揃っているので、料理に合わせて選ぶ楽しみがある。店主やスタッフに相談すれば、その日の料理に合う一本をおすすめしてくれるので、日本酒に詳しくない人でも安心だ。焼酎も芋、麦、米とバリエーション豊かで、ロック、水割り、お湯割りと好みのスタイルで楽しめる。特に芋焼酎は香り高い銘柄が揃っており、炭火焼きとの相性が抜群だ。ビールは生ビールに加え、瓶ビールやクラフトビールも用意されている。お酒が苦手な人には、ソフトドリンクやノンアルコールカクテルもあるので安心してほしい。飲み放題プランが用意されている場合もあるので、宴会利用の際は事前に確認するといいだろう。料理とお酒、両方に妥協しない姿勢が、この店の信頼感につながっている。",
