  lede: "金沢の繁華街・片町。香林坊から少し南、犀川に近い片町2丁目のビル1階に、フランス料理「PARIGOT（パリゴ）」はある。最寄りは北陸鉄道石川線の野町駅から徒歩約10分、片町バス停からなら徒歩5分、金沢駅からもバスで10分程度という、夜の街歩きにも組み込みやすい好立地だ。肩肘張ったオートクチュール仕立てではなく「パリの日常料理」をテーマにしたビストロスタイルで、20席のテーブル席を持つ落ち着いた空間。コース3種類と単品25品、ワインから創作カクテルまで揃うドリンク24品、そして料理に寄り添う一杯を提案してくれるソムリエ。記念日のサプライズやバースデープレートにも対応し、デートから接待まで頼れる大人の一軒。",
  date: "2026-05-26",
