  sideArticles: [],
  quote: "くすの樹は、近江町市場のすぐ隣、武蔵町のADビル2階に、北陸の天然魚と加賀の地酒で組む夜のコースを置く割烹居酒屋。観光客で賑わう片町ほど華やかすぎず、料亭ほど構えすぎない居心地が、金沢の台所の真横でちょうどよく成立している。金沢で「市場の余韻のまま、北陸の魚で夜を始めたい」と考えるとき、まさに、編集部が覚えておきたい一軒です。",
  quoteCite: "マチノワ編集部",
  closing: "近江町市場の喧騒から一歩入った夜を楽しむなら、金沢駅からの道のりを決めておくといい。新幹線で金沢駅に着いたら、まずは東口側のホテルに荷物を置き、徒歩で近江町市場へ向かう。昼のうちに香箱蟹、のどぐろ、鰤といった北陸の魚の売り場をひと回りして、市場の威勢のいい空気を吸っておくと、夜のコースの輪郭がつかみやすくなる。午後は兼六園・金沢21世紀美術館・ひがし茶屋街・主計町茶屋街を一通り回り、夕方は近江町市場に戻ってきて、そのまま武蔵が辻交差点の角からADビルの2階へ上がる流れが落ち着きやすい。18時前後にカウンターへ入って、ディナー平均9,000円前後のコースを軸に、のどぐろの蒸し寿司や季節の造りを中心に据えると、二時間ほどで北陸の海と加賀野菜の輪郭を一通り辿れる。二人のディナーなら、カウンターに並んで座って店主の手元を眺めながら、北陸三県の地酒を一杯ずつ合わせていく組み立てが向く。気の合う数人で集まる夜なら、半個室や掘りごたつ席を予約してコースをシェアし、石川・富山・福井の地酒を順番に開けていくと、北陸の夜がそのまま卓上に並ぶ。家族や金沢旅行の夜にも、ビジネスの会食にも対応しやすい店構えで、用途を伝えて予約しておくと、当日の席割りも組みやすい。ランチは予約のみの営業のため、昼に試したい場合は事前の予約を忘れずに。営業時間・料金・コース内容・定休日は時期で変わる可能性があるので、訪問前に電話 076-254-6846 もしくは公式情報での確認を。金沢で「観光地の中心ではなく、市場のすぐ隣で北陸の魚を主役にした夜を組みたい」と思ったとき、くすの樹は、その夜を任せて間違いのない店だ。",
