        purpose: "あっさり系の北海道ラーメンを探している人へ",
        desc: "ラーメンまるひらの軸は、釧路で60年以上続く老舗の流れを汲んだ、あっさり系の一杯にある。スープはカツオ節を主軸に取った清湯系で、見た目は透き通り、口に運ぶと魚介の出汁感が穏やかに広がる構造。札幌で「ラーメン」と聞いて多くの人が思い浮かべるこってり濃厚な味噌や、脂をしっかり乗せた一杯とは別系統の、釧路らしい澄んだ味わいが軸になっている。メニューは醤油・塩・ミックスの3種類で展開。なかでもミックスは、本店では裏メニュー扱いだった一杯で、塩のキレと醤油の香りを同時に楽しめるのが特徴だ。札幌の濃い味のラーメンが続いた後の口直しとして、あるいは胃に重さを残したくない昼食として、引き出しに入れておきたい一杯になる。スープの濃度や提供形態は時期によって調整される可能性があるため、現地での一杯はぜひ自分の舌で確かめてほしい。",
