        desc: "魚の光家の核となるのは、市場から仕入れた魚介を中心に据えた料理構成だ。海鮮丼や刺身、煮魚・焼き魚といった魚介料理を、ランチでもディナーでも軸に据えて組み立てている。「お食事処」を看板に掲げる業態だけあって、肩の張らない価格帯で日々の魚を味わえる構えになっており、特別な日のための高級店というよりは、日常の食卓として通える店としての立ち位置を取っている。徳力公団前という北九州市の生活圏のど真ん中で、昼も夜も同じ魚介軸で組み立てている食堂は意外と貴重で、「今日は魚が食べたい」と思った日にまっすぐ向かえる店として、徳力周辺の食卓の引き出しになりやすい。仕事帰りの一人飯、家族での夕食、平日のランチ会といったシーンを選ばず、北九州市内で魚介と聞いたら候補に挙げたい一軒だ。",
