    closing: "徳力公団前の生活圏でこの一軒を使うなら、昼から入るのがいい。最初に試したいのはランチタイムの海鮮丼を軸に試してみるのが筋がいい。市場からの仕入れがそのまま丼に落ちる構成のため、店の魚介の組み立てを一度の食事で確認でき、二度目以降の使い方の判断軸ができる。デート利用というよりは、家族のお出かけランチや、一人での落ち着いた平日昼ごはんに向く食堂業態だ。夜の時間帯は、刺身や定食を肴にゆっくり過ごす組み立てが取りやすく、仕事帰りに魚で食事を取る使い方もしやすい。所要時間はランチ利用で45分〜1時間、ディナー利用で1〜1.5時間を目安に。1名あたりの予算は、ランチ帯でおおむね2,000円前後、ディナー帯で4,000円前後が中心と見ておくと判断しやすい。土日祝のランチピーク（12時前後）は混雑することがあるため、時間を少しずらすか、開店直後を狙うと席に着きやすい。営業時間・定休日・メニュー・料金は時期や状況で変わる可能性があるため、訪問前に電話 093-600-2323 または公式情報での確認を推奨する。徳力公団前駅から徒歩圏、駐車場もあり、北九州都市圏のどこからでも訪れやすい立地だ。北九州・小倉南区で「魚を食べたい」と思った日、徳力の魚の光家は街の食卓として穏やかな置きどころになってくれる。",
