  sideArticles: [],
  quote: "cafe GRANOは、東京で7年修業した店主が八戸の郊外に開いたベーカリーカフェ。本日のパスタやオムライスといった食事を楽しみつつ、店内では焼きたてのパンも買える。八戸で「郊外でゆっくり食事をして、帰りに焼きたてのパンを持ち帰りたい」と思ったとき、妙まで足を延ばす理由になる一軒です。",
  quoteCite: "マチノワ編集部",
  closing: "海沿いの八戸を巡ってから郊外のカフェで昼を取るなら、朝からの流れをひと続きにしたい。八戸市内に泊まっているなら、朝は早起きして館鼻岸壁朝市や蕪島、種差海岸といった海沿いのスポットを車で巡り、八戸の朝の空気を味わっておく。昼は10時の開店以降を狙って、八戸工業大学そばのcafe GRANOへ。初訪問なら、スープとサラダが付く本日のパスタ1,480円を軸に、その日の旬の一皿を味わうのがわかりやすい。食事系をしっかり食べたい日は、特製オムライスやライス付きのハンバーグステーキ、ビーフカレーといったメニューに切り替えてもいい。食後は、こしあんと大納言を使ったまめぱんなど、店内に並ぶ焼きたてのパンを選んで持ち帰れば、翌朝の楽しみまで手に入る。サンドイッチはテイクアウトに対応しているため、午後のドライブのお供にも組み込みやすい。会計は現金のみなので、訪れる際は現金を用意しておきたい。午後はそのまま種差海岸の遊歩道を歩いたり、八戸市街地に戻って中心街の横丁を巡ったりと、海と街の両方を一日で味わう動線が組み上がる。営業は10:00〜15:30（L.O.15:00）、定休は月曜、ディナーは予約制での提供が予定されている。営業時間・定休日・メニュー・料金・支払い方法は時期や状況で変わる可能性があるため、訪問前に電話 050-8883-0996 もしくは公式情報での確認を。八戸で「郊外のカフェでゆっくり食事をして、焼きたてのパンも持ち帰りたい」と思ったとき、cafe GRANOは妙でその昼を満たしてくれる店だ。",
