      purpose: "昼にがっつり食べたい人へ",
      desc: "Kitchen Kenの軸にあるのは、気取らない洋食だ。看板はハンバーグで、ご飯・スープ・サラダにデザートとドリンクまで付いたセットで頼めるため、昼にこれ一皿で満足できる構成になっている。ほかにも黒豚を使ったカツカレーや、じっくり煮込んだビーフシチューのセット、ステーキのセットなど、洋食店らしいメニューがそろう。鹿児島らしく黒豚を使った一皿があるのも、地元で食べる洋食としてうれしいところだ。仰々しいコース料理ではなく、一皿でしっかり腹を満たせる定食感覚の洋食が中心で、これが地味に効く。昼に草牟田あたりで用事を済ませたとき、軽く済ませるのではなく、きちんと食べたい日に頼りになる。価格や提供内容は時期で変わる可能性があるため、訪問前に電話 099-227-7691 か公式情報での確認を勧めたい。",
