      purpose: "昼と夜で使い分けたい人へ",
      desc: "Kitchen Kenが面白いのは、時間帯で店の役割が変わる点だ。昼はセットの洋食をしっかり出す食事処として動き、夜はレンガ調の店内で洋酒を傾けたり、ダーツを楽しんだりできるダイニングバーへと表情を変える。同じ空間が、昼は定食感覚の洋食店、夜は一杯飲みながら過ごせるバーとして、目的に合わせて使い分けられる構成になっている。夜は遅い時間まで開いているため、食事のあとに腰を据えて飲みたい日や、二軒目として立ち寄りたい日にも合わせやすい。草牟田という生活エリアにありながら、夜にゆっくり過ごせる場所があるのは、近所に住む人にとって通う理由になる。営業時間や夜の営業内容は時期で変わる可能性があるため、夜に訪れる場合は、開いている時間帯を事前に確認しておくと確実だ。",
