      purpose: "誰とどう使えるか把握しておきたい人へ",
      desc: "Kitchen Kenの店内は、レンガ調の壁にソファを配した、洋風で落ち着いた雰囲気でまとめられている。テーブル席を中心に、開放感のある造りで、昼は食事に、夜は一杯飲みながら過ごす場として使い分けられる。店内には洋酒が並び、ダーツも備えているため、食後にそのまま腰を据えて楽しめるのも特徴だ。一人で昼食をとるのにも、友人や同僚と夜にテーブルを囲むのにも、用途を選ばず使える構えになっている。レンガとソファでまとめた空間は、肩肘張らずに長居できる温度感があり、これが地味にありがたい。気取らず入れる空気感がありながら、夜は遅い時間までゆっくりできるため、仕事帰りに立ち寄って一日の区切りをつけるのにも向く。ダーツを囲んで盛り上がりたい夜も、静かに食事を済ませたい昼も、同じ店で目的に合わせて使える。席の種類や利用できる時間帯、ダーツの利用可否などは時期や状況で変わる可能性があるため、人数や用途が決まっている場合は、事前に電話で相談しておくと落ち着く。",
