      desc: "Kitchen Kenがあるのは、鹿児島県鹿児島市草牟田二丁目。鹿児島県護国神社のほど近く、中心部から甲突川を渡って城西・草牟田方面へ入った生活エリアだ。鹿児島市電の加治屋町電停や市役所前電停からは少し距離があり、最寄りの鉄道駅からも離れているため、現実的には車で訪れるのが分かりやすい立地になる。駐車場が用意されているので、市内を車で動く日の昼食や、夜の一杯の行き先として組み込みやすい。天文館や鹿児島中央駅周辺の繁華街からは少し外れているぶん、混み合う中心部を避けて落ち着いて過ごせるのが、この立地ならではの良さだ。草牟田は学校や住宅、神社の並ぶ落ち着いた一帯で、観光で歩く街というより、地元の暮らしのそばにある場所だと言える。草牟田や城西で用事を済ませた帰り、あるいは護国神社へ立ち寄ったあとの食事として動線に乗せやすい。車で来るなら、中心部の駐車場探しに悩まずに済むのもありがたい。駐車場の台数・営業時間・定休日は時期で変わる可能性があるため、訪問前に電話または公式情報での確認を。",
