      purpose: "特別な食材で記念日を彩りたい人へ",
      desc: "通いたくなる理由を挙げるなら、まずこの店が扱う食材の幅だ。浪花亭では、天然ふぐを使ったコースやすっぽんのコースが用意されており、はもやおこぜといった、札幌の食卓では出会いにくい魚介も並ぶ。海産が豊かな北海道にあっても、こうした食材を専門の手仕事で味わえる場は限られる。だからこそ、季節の節目やここぞという日に選びたくなる。もう一つ、この店を語るうえで欠かせないのが名物の「飲むトマト酢」だ。これは航空会社JALの国内線ファーストクラスにも採用された一品で、食事の合間に口をすっきりと整えてくれる。会席のコースの流れの中で、こうした名物が一つ挟まることで、食事全体の記憶がぐっと立体的になる。同じ和食でも、浪花亭でしか味わえないものがある――その手応えが、また足を運びたいという気持ちにつながる。コースの内容や提供時期は変わる可能性があるため、目当ての食材がある場合は予約のときに確認しておきたい。これ、特別な日の店選びに地味に効いてくる。",
