      desc: "浪花亭の楽しみは会席だけにとどまらない。店には天ぷら専門の「成（なり）」があり、揚げたての天ぷらを味わう趣向も用意されている。会席の流れの中で揚げ物を楽しむのとはまた違い、天ぷらそのものに焦点を当てた時間は、食材の持ち味と職人の手際を間近で感じられる。さらに2026年5月からは、新たにうなぎ料理が加わった。北海道の店でうなぎをじっくり味わえる機会は貴重で、和食の引き出しがまた一つ増えたかたちだ。会席で季節を通して味わう日もあれば、天ぷらやうなぎに狙いを定めて訪ねる日もある――その時の気分で選び方を変えられるのが、この店の懐の深さだと思う。何を中心に据えるかで、同じ一軒が違う表情を見せてくれる。会席で土地の旬をたどる夜と、揚げたての天ぷらに向き合う夜では、過ごし方も自然と変わってくる。提供内容や席の種類は時期によって変わる可能性があるため、天ぷらやうなぎを目当てに行くなら、事前に電話で空席と内容を確かめておくと安心だ。",
