      purpose: "店の核となる料理を知りたい人へ",
      desc: "鮨ふみの中心にあるのは、おまかせで供される江戸前鮨だ。メニューから選ぶのではなく、その日その時の良質なネタを、大将が握りに仕立てて順に出していく。何が出るかを完全に決めきらず、仕入れと季節に委ねるスタイルなので、訪れるたびに皿の表情が変わる。大将は福喜鮨の本店をはじめ、高級ホテルや北新地で20年にわたって腕を磨いてきた職人で、江戸前の仕事を一貫して積み重ねてきた背景を持つ。鮨は流行の演出に寄せるよりも、ネタとシャリ、握りの基本を丁寧に重ねることに重きを置いているのが伝わってくる。だからこそ、特別な日の一度きりではなく、季節が変わるたびに通って確かめたくなる。江戸前鮨をきちんと味わいたい、という気持ちにまっすぐ応えてくれるのが、この店の核だと思う。おまかせを軸にしつつ、相談すれば一品料理にも応じてもらえるので、その日の気分にあわせて組み立てられるのも心強い。",
