  lede: "京阪電車の大和田駅で降りて、改札を出て住宅街へ少し入っていく。門真市のこのあたりは観光地でも繁華街でもなく、下町の空気が残る静かなエリアだ。入り組んだ路地を徒歩8分ほど歩くと、その一角に寿司 美奈吉がある。創業から半世紀あまり、移転を経て今の場所で暖簾を守ってきた、地元に根ざした小さな寿司店だ。ここの中心にあるのは、店主が自ら仕入れた食材を使い、寿司に和食とフレンチを織り交ぜて仕立てる和洋寿司コース。広いお座敷を備え、家族の記念日や法事、気の置けない仲間との宴会まで受け止めてきた一軒でもある。",
