      desc: "美奈吉が界隈の寿司店と違うのは、カウンターだけの店ではなく、ゆったりとした和のお座敷を構えている点だ。畳の広間には大きなテーブルが据えられ、12名ほどまでが膝を崩して座れる。2名から部屋を貸切にすることもでき、まわりを気にせず過ごせる。住宅街の一軒だからこそ、家族の集まりや気の置けない仲間との宴会を、自分たちのペースで楽しめる空間になっている。寿司店でこれだけの座敷を持つ店は多くなく、ここが通いたくなる理由のひとつだ。記念日やお祝い、忘年会や新年会といった節目の席はもちろん、法事のような改まった集まりにも応じてくれる。人数や予算に合わせて献立を組んでもらえる柔軟さもあり、幹事としては相談しやすい。畳に腰を下ろし、料理を囲んで時間を気にせず語らう――そんな昔ながらの宴の形が、ここにはまだ残っている。席数が限られ予約優先のため、座敷を使いたい日は早めに電話で押さえておくと確実だ。",
