      desc: "美奈吉の料理を語るうえで欠かせないのが、店主の手仕事だ。食材は店主自らが仕入れ、季節の魚を中心に一品ずつ手づくりで仕立てる。なかでも特徴的なのが、野菜や果物を彫って花や生き物の形にする日本の伝統技法「むきもの」だ。店主はこの野菜彫刻の名手として知られ、2025年に開かれた海外向けの大型イベント、スターウォーズ セレブレーション ジャパンのステージで、むきものの実演を披露している。コースの皿にも、人参や大根を細工した彩りがさりげなく添えられ、見て楽しむ要素が料理に加わる。もうひとつ、美奈吉が力を入れているのが寿司ケーキだ。ちらし寿司をケーキのように丸く盛りつけ、誕生日や記念日のサプライズに使えるもので、全国向けの通販もおこなっている。コースを注文した人の誕生日には、小さな寿司ケーキが用意される心づかいもある。寿司の腕に、むきものの技と遊び心が重なる――それが、この店ならではの持ち味だと思う。創業から半世紀あまり、地元で寿司を握り続けてきた店主だからこそ、こうした手仕事と気配りが自然に料理へ表れている。",
