      desc: "この店は、ラーメン一杯で終わらせず、しっかり腹を満たしたい人にも向いている。麺類のまわりに、定食やサイドメニュー、ごはんものがそろっているからだ。半チャンセットのようにラーメンと炒飯を組み合わせられる定食があり、唐揚げや餃子を合わせた定食も用意される。単品でも焼きめしや丼ぶり、唐揚げ、餃子といった一品が頼めるので、ラーメンに軽く一皿を足したいときにも、がっつり定食で食べたいときにも対応できる。ドリンク類もあり、食事として腰を据えて使える構成になっている。昼にしっかり食べたいランチにも、夕方からの一杯と一品にも合わせやすく、麺だけの専門店よりも使い勝手の幅が広い。気分でラーメンの種類を選び、そこへ炒飯や餃子を足して自分だけの組み合わせを作る――そんな楽しみ方ができるのが、この店の懐の深さだ。家族や同僚と来ても、それぞれが好きなものを頼んで満足できる。",
