      desc: "おばんざいと酒の店 信～shin～の軸は、店名がそのまま示すとおり、おばんざいにある。おばんざいとは、家庭の総菜のように季節の野菜や乾物、魚などを炊いたり和えたりした小鉢の料理のことで、この店では毎日8品から10品ほどが用意される。日によって並ぶ顔ぶれが替わるので、訪れるたびに違う取り合わせに出会えるのがおばんざいの楽しいところだ。カウンターに小鉢が並ぶ様子を眺めて、その日の気分で選ぶ――そんな、お惣菜屋さんの店先のようなやり取りが、そのまま夜の一杯につながっていく。一品ずつは控えめな量だから、いくつか頼んで少しずつ味わうことができ、一人でも数種類を試しやすい。家庭料理の延長にあるあたたかみのある皿を、店でていねいに仕立てて出してくれる。きょうは何があるだろうと考えながら暖簾をくぐる、その小さな期待が通う理由になる店だと思う。",
