      desc: "席のつくりが幅広いのも、いろいろな集まりにこたえてきた店らしいところだ。総席数は八十席を超え、座敷、掘りごたつ、テーブルの個室がそろい、ひとりや少人数ならカウンターに八席が用意されている。落ち着いて話したい顔合わせや法事には個室を、気軽に料理と酒を楽しみたい日にはカウンターをと、人数と用途で場所を選べる。二十五名から五十名規模の貸切にも対応するため、親族の集まりや会社の宴席といった大人数の場面にも使える。子ども連れのお祝いから年配の家族との会食まで、世代の違う集まりを一つの店で受けられるのは、個室と座敷が整っているからこそだ。掘りごたつなら足を伸ばせて、長い時間の会食でも体がつらくなりにくい。少人数で訪れるなら、その日の一品を相談しながらカウンターで頼むのも気持ちがいい。席種や個室の空き具合は日によって変わるので、人数が決まっているなら予約のときに伝えておくと段取りがいい。",
