  sideArticles: [],
  quote: "梁山泊は、観光でにぎわう奈良の中心にありながら、地元の家族が節目のたびに帰ってくる日本料理の店。古都で半世紀、会席と七十種の一品、各地の銘酒で人生の祝いと別れを支えてきた。奈良で大切な一日を誰かと囲むなら、まず名前を挙げたい一軒です。",
  quoteCite: "マチノワ編集部",
  closing: "誰と、どんな日に来るかで、梁山泊の使い方は大きく変わる。家族の祝い事や法事で集まるなら、人数と趣旨を伝えて個室を押さえ、会席のコースを軸に組むのがいちばん収まりがいい。お食い初めや顔合わせなら、祝い膳の用意があるかもあわせて相談しておきたい。県外から親族が来るなら、近鉄奈良駅から徒歩八分という分かりやすい道のりが案内の負担を軽くしてくれる。一人や二人でふらりと訪ねるなら、カウンターに腰かけて、のどぐろや季節の一品を肴に奈良の酒を傾けるのがこの店らしい。昼に奈良公園や東大寺を歩いたあと、夕方の会席で一日を締めるという観光の使い方もはまる。所要は会席をゆっくり通すなら二時間ほど、一品と酒で軽く過ごすなら一時間半ほどを見ておくと落ち着く。予算は昼の点心が三千円台、夜の会席はコースによって六千円前後から一万円ほどが目安になる。祝い事や大人数の宴席、昼の利用は予約が前提になりやすいので、人数と日取りが決まったら早めに席を押さえておきたい。内容は時期で変わることがあるため、目当てがあるなら事前に店へ問い合わせておくと確実だ。古都奈良で大切な一日を囲む店を探しているなら、梁山泊は長く頼れる一軒になる。",
