      purpose: "宮崎牛を予算に合わせて選びたい人へ",
      desc: "使われているのは宮崎牛の内もも肉だ。和牛の品評会で評価を重ねてきた産地の牛で、脂が控えめで赤身がしっかりしているぶん、揚げてもくどさが残りにくい。メニューは定食が中心で、標準の牛かつ定食から、宮崎牛を使った定食、肉量を増やした特選の宮崎牛かつ定食まで、肉の種類とグラム数で段階が分かれている。価格はおおむね、標準の定食が二千円前後から、特選になると四千円台までと幅があり、その日の腹具合や予算に合わせて選び分けられる。卓上を補う一品としてポテトサラダなどの副菜もあり、定食に添えれば食事としての満足感が増す。赤身を主役に据えた構成なので、揚げ物が重く感じやすい人でも食べ進めやすい。グラム数で段階が選べるので、軽く済ませたい昼は標準の定食を、しっかり食べたい日は宮崎牛や特選を、と気分や予算で振り分けられるのもありがたい。価格や品揃えは時期で動くことがあるため、訪れる前に公式の情報で確かめておきたい。",
