  title: "西熊本・薄場のイタリアン、ピノッキオ。本場仕込みの一皿を昼から気軽に",
  titleHTML: "ピノッキオ、<br>薄場の<em>イタリア。</em>",
  subtitle: "本場仕込みの料理を気負わず味わう、熊本市南区薄場の一軒",
  lede: "熊本市の中心部から国道を南へ下り、JR西熊本駅の界隈まで来ると、街は住宅と小さな商いが混ざり合う落ち着いた表情になる。薄場一丁目、熊本銀行の支店にほど近い一角に、うっかりすると通り過ぎてしまいそうな小さな店構えがある。それがイタリア料理のピノッキオだ。店主は若い頃にイタリア北西部の街アオスタで腕を磨いた人で、帰国してこの地で本場仕込みの料理を出し続けている。気取った構えではなく、昼はランチを目当てに人が集まり、午後になると静かに落ち着く——そんな、日常のなかで本格的な一皿に出会える店だ。手打ちのパスタや地の野菜を生かした料理を、肩肘張らずに味わえる場所として、薄場のまちに静かに根を下ろしている。観光地のにぎわいとは縁のない住宅地で、近所の人にも、少し遠くから車を走らせてくる人にも選ばれ続けているのは、料理そのものに通う理由があるからだろう。ここでは、その理由を、店の成り立ち・昼の使い方・料理の中身・席の居心地・行き方という順に、ひとつずつほどいていきたい。",
  date: "2026-06-05",
  reading: "",
