      purpose: "実際に行くときの道順と時間帯を知りたい人へ",
      desc: "店があるのは熊本市南区薄場一丁目。最寄りはJR鹿児島本線の西熊本駅で、駅からは少し歩く距離にあり、車で訪れる人も多い立地だ。目印は近くにある熊本銀行の薄場支店。店構えが控えめなので、初めてだと通り過ぎやすく、住所と目印を頭に入れてから向かうと迷いにくい。営業は昼の十一時半から十四時ごろまでと、夜の十七時半から二十一時半ごろまでの二部制で、定休は月曜にあたる。中心部の繁華街にある店ではないので、ふらりと立ち寄るというより、目的地として足を運ぶ一軒だ。昼の混み合う時間帯はにぎわうため、確実に座りたいなら開店まもない時間か、午後の落ち着いた頃を狙うとよい。車で来るなら駐車の場所を、電車なら西熊本駅からの徒歩ルートを、出かける前に地図で一度たどっておくと当日の動きがなめらかになる。営業時間や定休日は変わることがあるため、来店前に096-358-3332へ一度確かめておきたい。",
