      desc: "Giselleの軸になっているのは、国内外から集められた雑貨だ。とりわけフランスや欧米諸国から仕入れたアンティークは完全な一点もので、店内の至る所に並んでいる。リボンやボタンといった手芸の小物も、お洒落で珍しいものがそろい、つくる人の心をくすぐる。なかでもペーパーナプキンは地域でも有数の品揃えと言われるほどで、デコパージュなどの素材を探す人の目当てになっている。決まった棚に同じものが並び続ける店ではなく、その時々で出会うものが変わるのが古いものを扱う店の面白さで、掘り出し物を見つけるような感覚で棚を巡れる。生活を彩る小物から手芸の材料まで、用途も値段も幅があるので、はっきりした目当てがなくても、ふらりと立ち寄って眺める時間がちゃんと成立する。何を探しに行くというより、何に出会えるかを楽しむ――そんな構えで向き合うと、この店の棚はぐっと豊かに見えてくる。",
