      desc: "カレーと並んでこあの助を語るうえで欠かせないのが、創作どんぶりだ。なかでも豚納豆丼は店の名物として知られ、タイ料理店でありながら和の食材を大胆に取り込んだ一杯になっている。タイカレーの店に納豆の丼があるという意外な組み合わせは、タイと日本が同居する台所という店のコンセプトを、もっとも分かりやすい形で見せてくれる一品だ。タイ料理を食べに来たはずが、気づけば次は丼を頼みに来ている――そんな通い方ができるのが、この店のメニュー構成の面白さだ。カレーの日もあれば、丼の日もある。同じ店に通いながら、その日の気分でタイと日本を行き来できる懐の深さが、一度きりで終わらせない理由になっている。何度か足を運ぶうちに、自分の定番が一つずつ増えていく――そういう付き合い方がしっくりくる店だ。",
