      purpose: "店の核となる一杯の魅力を知りたい人へ",
      desc: "麺屋野条の看板は、店名とともに覚えておきたい一杯――極み鶏白湯らぁめんだ。鶏のうまみをじっくり引き出したスープは、濃厚でありながら後味に重さを残さない。鶏清湯ラーメンの専門店として打ち出しているとおり、軸にあるのは鶏一本で勝負するという姿勢だ。鶏白湯は炊き方ひとつで印象が大きく変わるが、ここのスープは食べた人が思わず濃厚だと口にするほどの密度を持ちながら、最後まで飲み進められるバランスに整えられている。一杯のなかに、鶏のコクと滑らかな口当たり、そして麺との一体感が同居している。何種類もの味を並べて流行を追うのではなく、鶏のスープをどこまで突き詰められるかに照準を合わせた店だ。だからこそ、最初の一口で店の狙いがまっすぐ伝わってくる。寒い日に体を内側から温めたいとき、しっかり食べた満足感がほしいとき――鶏白湯の一杯は、その両方に応えてくれる。",
