  sideArticles: [],
  quote: "麺屋野条は、阪急門戸厄神の駅前で、台湾仕込みの鶏白湯らぁめんを出す専門店。海を渡って腕を磨いた店主が、地元・兵庫の醤油を傍らに置いて打つ一杯には、作り手の歩いてきた道のりが映っている。西宮で鶏白湯と聞いたら、思い出してほしい一軒です。",
  quoteCite: "マチノワ編集部",
  closing: "なぜ西宮の駅前で、台湾帰りの店主が打つ鶏白湯なのか――その答えは、門戸厄神まで足を運んで一杯すすれば腑に落ちる。駅の改札を出て二分、店に着いたらまずは看板の極み鶏白湯らぁめんを頼みたい。鶏のうまみをまっすぐ受け止めるなら、最初の一杯はシンプルに鶏白湯と向き合うのがいい。カウンターに座れば、目の前に並ぶ播州龍野の醤油が、この一杯の土台を教えてくれる。一人なら短い時間で集中して食べ切る使い方が収まりよく、家族や友人と来るなら、厄除けで知られる門戸厄神東光寺の参拝とセットにすると、半日の予定として過不足ない。所要は混んでいなければ三十分ほど、食事どきのピークなら待ち時間を見込んでおくと気が楽だ。予算は専門店の一杯として無理のない範囲だが、メニューや価格は時期で動くので、訪れる前に電話や公式SNSで確かめておくと確実だ。オープンして間もない時期は売り切れや営業時間の変動もありうるので、その点だけ頭に入れて向かえば、駅前の鶏白湯を気持ちよく味わえる。",
