      desc: "具体的な楽しみは、メニューの幅にある。温蕎麦も冷蕎麦もそろい、看板格の鴨南そばは、やわらかな鴨肉と澄んだあっさりめの出汁の組み合わせが手繰っていて飽きにくい。揚げたての衣とつゆが合う肉ごぼう天そばも人気の一杯だ。蕎麦だけで物足りない日には、親子丼にミニ蕎麦を添えたセットや、甘めで濃いめに仕上げたカツ丼を合わせると満足度が上がる。夜には蕎麦に合わせて楽しむ一品料理が加わり、飲み放題のついた蕎麦呑みの豚しゃぶコースなど、腰を据えて過ごすための選択肢も用意されている。季節ごとの期間限定メニューが入ることもあるので、その日の品書きを眺めてから決めるのも楽しい。温かい蕎麦で出汁の旨味を味わうか、冷たい蕎麦で麺のコシと喉ごしを楽しむか、その日の気分で振れ幅があるのもいい。蕎麦に甘めの丼を合わせる食べ方は、昼にしっかり食べたい日の定番になってくれる。メニューや価格は時期で動くので、気になる一品があれば訪れる前に電話や公式の案内で確かめておくと確実だ。蕎麦単品から丼セット、夜のコースまで、その日の腹具合と気分で選び分けられる懐の広さがある。",
