      purpose: "誰と、どんな気分で行く店かを知りたい人へ",
      desc: "席はカウンター、テーブル、小あがりの座敷で構成され、規模はおよそ十九席。一軒家を思わせるすっきりとした外観の内側は、清潔感のある落ち着いた空間で、ゆったりと過ごせる。カウンターがあるので一人で来て静かに蕎麦と向き合うのにも向くし、テーブルや小あがりは二人や家族連れ、少人数の集まりにちょうどいい。子供椅子の用意があり、座敷で足を崩せる席もあるため、小さな子を連れた食事でも肩肘張らずに済む。昼は近所の常連や仕事の合間の客で、夜は蕎麦呑みを楽しむ大人で――時間帯によって店の空気が移り変わるのも、ここで過ごす面白さのひとつだ。観光客でにぎわう繁華街の店とは違い、生活圏の中で気負わず通える距離感がある。カウンター越しに調理の手元が見えるのも、一人で来たときにはちょっとした楽しみになる。小あがりは荷物を置いて足を伸ばせるので、買い物帰りや子連れの食事で重宝するはずだ。昼の慌ただしくない時間に静かに過ごすか、夜にゆっくり腰を据えるかで、同じ席でも居心地の感じ方が変わってくる。誰と来ても収まりのいい席配りだから、用途を選ばずに使えるのがありがたい。",
