      desc: "具体的な居心地のよさは、飛鳥乃湯泉の目の前という立地が支えている。飛鳥乃湯泉は飛鳥時代の建築様式を取り入れた道後温泉の別館で、湯あがりに外へ出れば、もう目の前にこの店がある。体が火照っているうちに、数歩で一杯にたどり着ける距離感は、ほかではなかなか得られない贅沢だ。道後温泉本館や道後商店街もすぐ近くで、温泉と土産物店と飲み屋が徒歩圏にぎゅっと集まる道後らしい密度の中に、この店は位置している。湯めぐりの合間に喉を潤す、本館を見物したあとの余韻にひたる、商店街を冷やかして小腹を満たす――界隈での過ごし方の選択肢に、自然と組み込める場所だ。温泉施設の営業時間や混み具合は時期で変わるので、湯と一杯をどう組み合わせるかは、その日の動き方に合わせて決めるといい。温泉街の中心で、湯と酒が地続きになっている。それがこの立地の一番の強みだ。",
