  sideArticles: [],
  quote: "道後ハイボール酒場は、飛鳥乃湯泉の目の前で湯あがりの一杯を引き受ける、道後の新しい寄り道だ。2025年秋に生まれたばかりの店ながら、温泉と酒が数歩で地続きになる立地は、この街でこそ成り立つもの。湯けむりの余韻を肴にハイボールを傾けたくなったら、思い出してほしい一軒です。",
  quoteCite: "マチノワ編集部",
  closing: "湯から上がって火照った体のまま、数歩で冷えた一杯にたどり着ける――この距離感を頭に入れておくと、道後の夜の組み立てがぐっと楽になる。日中は道後温泉本館や飛鳥乃湯泉で湯を堪能し、夕方に道後商店街を冷やかして、その仕上げにこの店へ。一人旅なら、カウンター気分でその日に歩いた道後の景色を思い返しながら静かに一杯。連れがいるなら、湯あがりの感想を言い合いながら軽く飲んで、また夜の散歩に戻るのもいい。腰を据えて食事をとるための店というより、観光のしめや湯あがりの景気づけに、気軽に立ち寄る一杯が似合う。道後温泉駅からは商店街を抜けてすぐ、飛鳥乃湯泉の目の前という分かりやすさだから、初めての街でも迷いにくい。予算感や所要時間はその日の飲み方しだいで、軽く一杯なら短い滞在で十分、腰を落ち着けるなら時間に余裕を見ておきたい。営業時間や定休日は時期で動くことがあるので、夜遅めに向かうなら事前に当日の営業を確かめてから動くと確実だ。湯の街を歩き切った足で、最後の一杯を道後で締める。その締めくくりに、ちょうどいい一軒だ。",
