  lede: "久留米と聞いて思い浮かぶ味は、ラーメンや焼き鳥が先かもしれない。けれど市街地から少し北へ、宮ノ陣の田園地帯まで足を延ばすと、田んぼ道の先に蕎麦の一軒家が静かに佇んでいる。蕎麦処 一閑人は、北海道産の蕎麦粉を石臼で挽き、香り高い蕎麦を昼の時間だけ供する蕎麦専門店だ。西鉄甘木線の学校前駅から歩いて数分、のどかな風景の中に構えるその店は、観光地のにぎわいとは無縁の場所で、蕎麦と静かに向き合うための時間を用意している。中庭を眺めながら一枚を待ち、運ばれてきた蕎麦をゆっくり手繰る――慌ただしい日常から少し離れて昼を過ごしたいとき、ここはちょうどいい目的地になる。久留米でわざわざ蕎麦を、と思ったときに思い出したい一軒を、その魅力と使い方とともに見ていきたい。",
